(() => {
 const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const $=id=>document.getElementById(id);
 function open(index,phase){const j=JIEQI[index],h=j.sanhou[phase],k=window.SeasonKnowledge.get(index,phase),dateRange=range(termStart+phase*5*DAY,(phase===2?termEnd:termStart+(phase+1)*5*DAY)-DAY);const poem=k.poem,lines=poem.lines.replace(/([，。！？])/g,'$1\n').trim();
 const sequence=`<div class="phase-sequence"><h3>${escape(j.name)}的三候 · 每候约五日</h3><ol>${j.sanhou.map((p,i)=>`<li class="${i===phase?'current':''}"><small>${escape(p[0])}</small>${escape(p[1])}</li>`).join('')}</ol></div>`;
 const sources=`<div class="reading-sources"><a href="${k.source}" target="_blank" rel="noopener">候名参考：《月令七十二候集解》 ↗</a><a href="${k.culturalSource}" target="_blank" rel="noopener">延伸阅读：节气的习俗与故事 ↗</a><p>民俗有地域差异，传说与现代事实分开阅读。页面按日期展示，候期以约五日划分。</p></div>`;
 const body=`<div class="reading-header"><h2>${escape(h[1])}</h2><p class="reading-lead">${escape(k.phase.summary)}</p></div><div class="reading-tabs" role="tablist" aria-label="选择解读栏目">${['看懂物候','由来与故事','生活习俗','相关诗句'].map((name,i)=>`<button type="button" role="tab" id="readingTab${i}" aria-controls="readingPanel${i}" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-reading-tab="${i}">${name}</button>`).join('')}</div><section class="reading-panel" id="readingPanel0" role="tabpanel" aria-labelledby="readingTab0" tabindex="0"><div class="reading-section"><h3>这幅画在说什么？</h3><p>${escape(k.phase.explanation)}</p><p class="science-note">${escape(k.phase.modern)}</p></div>${sequence}</section><section class="reading-panel" id="readingPanel1" role="tabpanel" aria-labelledby="readingTab1" tabindex="0" hidden><div class="reading-section"><h3>${escape(j.name)}，何以得名？</h3><p>${escape(k.origin)}</p></div><div class="reading-section"><h3>${escape(k.story[0])}<span class="story-kind">${escape(k.story[1])}</span></h3><p>${escape(k.story[2])}</p></div>${sources}</section><section class="reading-panel" id="readingPanel2" role="tabpanel" aria-labelledby="readingTab2" tabindex="0" hidden><div class="reading-section"><h3>人们怎样过这个时节？</h3><ul class="customs-list">${k.customs.map(p=>`<li>${escape(p)}</li>`).join('')}</ul><p class="reading-prompt">问问家人：你的家乡在${escape(j.name)}前后，会吃什么、做什么？同一个节气，也可能有不同的生活记忆。</p></div>${sources}</section><section class="reading-panel" id="readingPanel3" role="tabpanel" aria-labelledby="readingTab3" tabindex="0" hidden><figure class="poem-block"><blockquote class="poem-lines">${escape(lines)}</blockquote><figcaption class="poem-credit">${escape(poem.dynasty)} · ${escape(poem.author)}《${escape(poem.title)}》</figcaption></figure><h3>读成今天的话</h3><p>${escape(poem.reading)}</p><p class="poem-note">本页按节气或季节意象选配诗句，并不表示每首诗都写于该节气当天。</p></section>`;
 $('drawer').classList.add('reading-drawer');openSheet(`${j.name} · ${h[0]} · ${dateRange}`,body);$('drawer').scrollTop=0;
 }
 function select(n,focus=false){const tabs=[...$('drawerBody').querySelectorAll('[data-reading-tab]')];if(!tabs.length)return;tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===n));tab.tabIndex=i===n?0:-1;$('readingPanel'+i).hidden=i!==n});if(focus)tabs[n].focus({preventScroll:true});const top=$('drawer').querySelector('.reading-header');if($('drawer').scrollTop>top.offsetHeight)$('drawer').scrollTo({top:top.offsetHeight,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
 document.addEventListener('DOMContentLoaded',()=>{$('drawerBody').addEventListener('click',event=>{const b=event.target.closest('[data-reading-tab]');if(b)select(Number(b.dataset.readingTab))});$('drawerBody').addEventListener('keydown',event=>{const b=event.target.closest('[data-reading-tab]');if(!b)return;let i=Number(b.dataset.readingTab);if(event.key==='ArrowRight')i=(i+1)%4;else if(event.key==='ArrowLeft')i=(i+3)%4;else if(event.key==='Home')i=0;else if(event.key==='End')i=3;else return;event.preventDefault();select(i,true)});$('drawer').addEventListener('close',()=>{$('drawer').classList.remove('reading-drawer')})});
 window.SeasonReading={open};
})();
